// This code has been fully generated by an AI.
//
// Tests for the DOM-free browser modules. Run: node --test internal/web/jstest/

import { test } from "node:test";
import assert from "node:assert/strict";

import { buildStyle, basemapVisibility, bounds } from "../static/map-style.js";
import { coordinates, positionAt, xAxis, chartSeries, thin, rangeIndices, sectionCoordinates, thinnedRange } from "../static/activity-data.js";

const cfg = {
  default: "osm",
  basemaps: [
    { id: "osm", label: "OSM", tiles: ["https://t/{z}/{x}/{y}.png"], tileSize: 256, maxzoom: 19, attribution: "© OSM" },
    { id: "topo", label: "Topo", tiles: ["https://topo/{z}/{x}/{y}.png"], tileSize: 256, maxzoom: 17, attribution: "© Topo" },
  ],
  overlays: [{ id: "dop-by", label: "DOP", tiles: ["https://wms?BBOX={bbox-epsg-3857}"], tileSize: 256, maxzoom: 20, attribution: "© BVV" }],
};

test("buildStyle shows only the selected basemap and enabled overlays", () => {
  const style = buildStyle(cfg, "topo", ["dop-by"]);
  assert.equal(style.version, 8);
  const vis = Object.fromEntries(style.layers.map((l) => [l.id, l.layout.visibility]));
  assert.deepEqual(vis, { "base-osm": "none", "base-topo": "visible", "overlay-dop-by": "visible" });
  assert.equal(style.sources["base-topo"].maxzoom, 17);
  assert.equal(style.sources["overlay-dop-by"].attribution, "© BVV");
});

test("buildStyle falls back to the default for unknown basemaps", () => {
  const style = buildStyle(cfg, "gone");
  assert.equal(style.layers.find((l) => l.layout.visibility === "visible").id, "base-osm");
  assert.equal(style.layers.find((l) => l.id === "overlay-dop-by").layout.visibility, "none");
});

test("basemapVisibility toggles exactly one layer", () => {
  assert.deepEqual(basemapVisibility(cfg, "osm"), [["base-osm", "visible"], ["base-topo", "none"]]);
});

test("bounds of coordinates", () => {
  assert.deepEqual(bounds([[12.8, 48.2], [12.9, 48.1], [12.7, 48.3]]), [[12.7, 48.1], [12.9, 48.3]]);
  assert.equal(bounds([]), null);
});

const stream = {
  t: [0, 1, 2, 3],
  lat: [48.2, null, 48.3, 48.4],
  lon: [12.8, null, 12.9, 13.0],
  dist: [0, 500, null, 1500],
  speed: [5, 10, null, 2.5],
  hr: [null, null, null, null],
  alt: [400, 401, 402, 403],
};

test("coordinates skip GPS dropouts", () => {
  assert.deepEqual(coordinates(stream), [[12.8, 48.2], [12.9, 48.3], [13.0, 48.4]]);
  assert.deepEqual(coordinates({ t: [0] }), []);
});

test("positionAt falls back to the last known position", () => {
  assert.deepEqual(positionAt(stream, 1), [12.8, 48.2]);
  assert.deepEqual(positionAt(stream, 99), [13.0, 48.4]);
  assert.equal(positionAt({ t: [0] }, 0), null);
});

test("xAxis uses monotonic distance in km, else minutes", () => {
  const ax = xAxis(stream);
  assert.equal(ax.unit, "km");
  assert.deepEqual(ax.values, [0, 0.5, 0.5, 1.5]);
  assert.deepEqual(xAxis({ t: [0, 60, 120] }).values, [0, 1, 2]);
});

test("chartSeries keeps channels with data and converts speed to km/h", () => {
  const series = chartSeries(stream);
  assert.deepEqual(series.map((s) => s.key), ["alt", "speed"]);
  assert.deepEqual(series[1].values, [18, 36, null, 9]);
});

test("thin keeps every n-th sample and maps indices back", () => {
  const x = [0, 1, 2, 3, 4, 5, 6];
  const r = thin(x, [{ key: "a", values: x.map((v) => v * 10) }], 3);
  assert.deepEqual(r.index, [0, 3, 6]);
  assert.deepEqual(r.x, [0, 3, 6]);
  assert.deepEqual(r.series[0].values, [0, 30, 60]);
  assert.equal(thin(x, [], 100).x, x);
});

test("rangeIndices finds the samples of a lap", () => {
  const t = [0, 1, 2, 5, 6, 10];
  assert.deepEqual(rangeIndices(t, 2, 6), [2, 4]);
  assert.deepEqual(rangeIndices(t, 0, 0), [0, 0]);
  assert.equal(rangeIndices(t, 3, 4), null);
  assert.equal(rangeIndices(t, 11, 20), null);
});

test("sectionCoordinates skips dropouts", () => {
  const s = { lat: [48, null, 48.2, 48.3], lon: [12, 12.1, 12.2, 12.3] };
  assert.deepEqual(sectionCoordinates(s, 0, 2), [[12, 48], [12.2, 48.2]]);
  assert.deepEqual(sectionCoordinates({}, 0, 2), []);
});

test("thinnedRange maps a sample range to thinned chart points", () => {
  assert.deepEqual(thinnedRange([0, 3, 6, 9], 2, 7), [1, 2]);
  assert.equal(thinnedRange([0, 3, 6, 9], 4, 5), null);
});
